const excluir = /\b(senior|sr|lead|principal|manager|head|trainee|intern|practicante|pasante|arquitecto)\b/i;
const textoPlano = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const listaPaises = ['united states', 'usa', 'canada', 'mexico', 'brazil', 'brasil', 'united kingdom', 'germany', 'israel', 'india', 'australia', 'spain', 'france', 'argentina', 'chile', 'peru', 'colombia'];
function decidir(location, description) {
  const ubicacion = textoPlano(location);
  const descripcion = textoPlano(description);
  const texto = `${ubicacion}\n${descripcion}`;
  const colombiaExplicita = /\b(colombia only|remote in colombia|located in colombia|based in colombia|candidates? (?:must be )?located in colombia|applicants? (?:must be )?located in colombia|open to candidates in colombia|work from colombia)\b/.test(texto);
  const mundialExplicito = /\b(open worldwide|worldwide remote|open to applicants worldwide|any country|work from anywhere)\b/.test(texto);
  const restringidoAOtroPais = listaPaises.some(pais => pais !== 'colombia' && new RegExp(`\\b${pais.replace(/ /g, '[ -]')} only\\b`).test(texto));
  if (restringidoAOtroPais) return 'NO_COLOMBIA';
  if (colombiaExplicita || mundialExplicito) return 'COLOMBIA';
  return 'REVISAR';
}
return $input.all().map(({ json }) => {
  const title = json.title || '';
  const description = json.descriptionText || json.descriptionHtml || '';
  const location = json.location || json.jobLocation || '';
  const url = json.url || json.link || json.jobUrl || '';
  const elegibilidad = decidir(location, description);
  return { json: { title, company: json.companyName || json.company || '', location, description: String(description).replace(/<[^>]*>/g, '').slice(0, 500), url, elegibilidad } };
}).filter(({ json }) => json.url && !excluir.test(json.title));

const escapeHtml = value => String(value || '').replace(/[&<>]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch])).split(String.fromCharCode(34)).join('&quot;').split(String.fromCharCode(39)).join('&#39;');
const ofertas = $input.all();
let html = `<h2>Ofertas remotas confirmadas para Colombia (${ofertas.length})</h2><ul>`;
for (const { json } of ofertas) {
  const href = /^https:\//i.test(json.url) ? json.url : '#';
  html += `<li><b>${escapeHtml(json.title)}</b> - ${escapeHtml(json.company)}<br>Ubicación: ${escapeHtml(json.location)}<br><a href="${escapeHtml(href)}">Ver oferta</a></li>`;
}
if (!ofertas.length) html = '<p>No hubo ofertas con elegibilidad geográfica confirmada.</p>';
return [{ json: { html, count: ofertas.length } }];
